/** Свободное хождение (механика JOURNEY) — JOURNEY, JOURNEY SOLO, QUEST, QUEST SOLO, RUBG и БОГАЧ. */
export const isJourneyLike = (m: MapMode | undefined): boolean => m === 'journey' || m === 'journey1p' || m === 'rubg' || m === 'quest' || m === 'quest1p' || m === 'bogach' || m === 'frendy';
/** Одиночные режимы: играет только хост, остальные — зрители (можно стартовать одному). */
export const isSoloMode = (m: MapMode | undefined): boolean => m === 'skill' || m === 'journey1p' || m === 'classic1p' || m === 'quest1p';
/** Квестовые режимы (QUEST / QUEST SOLO): индивидуальная игра, задания на доверие, концовки. */
export const isQuestMode = (m: MapMode | undefined): boolean => m === 'quest' || m === 'quest1p';
/** v0.76: режимы, где ПАТРУЛЬНЫЕ боссы ЛОВЯТ игроков: QUEST/QUEST SOLO (как было)
    и JOURNEY/JOURNEY SOLO (v0.76), БОГАЧ (v0.104).
    RUBG не ловит — там своя механика занятий ячеек (rubgTryJob). */
export const isBossCatchMode = (m: MapMode | undefined): boolean => m === 'quest' || m === 'quest1p' || m === 'journey' || m === 'journey1p' || m === 'bogach';
/** v0.104: режим БОГАЧ — битва богатых на монетах (общие задания, вылет на нуле монет). */
export const isBogachMode = (m: MapMode | undefined): boolean => m === 'bogach';
/** v0.123: режим FRENDY — хеллоуинский хоррор: свободное хождение, микросхемы, печь, супер-босс Френди. */
export const isFrendyMode = (m: MapMode | undefined): boolean => m === 'frendy';
/** Базовый режим для кнопок верхней панели редактора (SOLO-вариант светится на базе). */
export const baseModeOf = (m: MapMode | undefined): MapMode => (m === 'classic1p' ? 'classic' : m === 'journey1p' ? 'journey' : m === 'quest1p' ? 'quest' : (m ?? 'classic'));
/** SOLO-вариант базового режима (skill всегда solo; у RUBG solo нет — null). */
export const soloVariantOf = (m: MapMode): MapMode | null => (m === 'classic' ? 'classic1p' : m === 'journey' ? 'journey1p' : m === 'quest' ? 'quest1p' : m === 'skill' ? 'skill' : null); // v0.123: FRENDY — соло-вариант не нужен (можно играть хоть одним игроком без переключателя)
